import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

const FormQuestion = ({
  question,
  numbering,
  handleAnswer,
  handleAddFollowUp,
}) => {
  const [newQuestion, setNewQuestion] = useState('');

  return (
    <div className="border rounded-lg p-4 mb-4 bg-white">

      <h2 className="font-bold text-lg mb-2">
        {numbering}
      </h2>

      <p className="mb-4">{question.text}</p>

      {/* Answer Input */}
      {question.type === 'Short Answer' ? (
        <input
          type="text"
          placeholder="Write your answer..."
          value={question.userAnswer || ''}
          onChange={(e) =>
            handleAnswer(question.id, e.target.value)
          }
          className="border p-2 rounded w-full"
        />
      ) : (
        <select
          value={question.userAnswer || ''}
          onChange={(e) =>
            handleAnswer(question.id, e.target.value)
          }
          className="border p-2 rounded w-full"
        >
          <option value="">Select</option>
          <option value="True">True</option>
          <option value="False">False</option>
        </select>
      )}

      {/* Add Follow-up */}
      <div className="mt-4 flex gap-2">

        <input
          type="text"
          placeholder="Add follow-up question..."
          value={newQuestion}
          onChange={(e) => setNewQuestion(e.target.value)}
          className="border p-2 rounded flex-1"
        />

        <button
          onClick={() => {
            if (!newQuestion.trim()) return;

            handleAddFollowUp(question.id, newQuestion);

            setNewQuestion('');
          }}
          className="bg-purple-500 text-white px-4 py-2 rounded"
        >
          Add
        </button>

      </div>

      {/* Children */}
      {question.children?.length > 0 && (
        <div className="ml-8 mt-4 border-l-4 pl-4">

          {question.children.map((child, index) => (
            <FormQuestion
              key={child.id}
              question={child}
              numbering={`${numbering}.${index + 1}`}
              handleAnswer={handleAnswer}
              handleAddFollowUp={handleAddFollowUp}
            />
          ))}

        </div>
      )}
    </div>
  );
};

const FormPage = () => {
  const [questions, setQuestions] = useState([]);

  useEffect(() => {
    const saved = localStorage.getItem('questions');

    if (saved) {
      setQuestions(JSON.parse(saved));
    }
  }, []);

  // Update User Answer
  const updateAnswer = (id, value, items = questions) => {
    return items.map((item) => {
      if (item.id === id) {
        return {
          ...item,
          userAnswer: value,
        };
      }

      return {
        ...item,
        children: updateAnswer(id, value, item.children),
      };
    });
  };

  const handleAnswer = (id, value) => {
    const updated = updateAnswer(id, value);

    setQuestions(updated);

    localStorage.setItem(
      'questions',
      JSON.stringify(updated)
    );
  };

  // Add Follow Up Question
  const addFollowUp = (
    parentId,
    questionText,
    items = questions
  ) => {
    return items.map((item) => {

      if (item.id === parentId) {

        const child = {
          id: Date.now() + Math.random(),
          text: questionText,
          type: 'Short Answer',
          answer: '',
          userAnswer: '',
          children: [],
        };

        return {
          ...item,
          children: [...item.children, child],
        };
      }

      return {
        ...item,
        children: addFollowUp(
          parentId,
          questionText,
          item.children
        ),
      };
    });
  };

  const handleAddFollowUp = (
    parentId,
    questionText
  ) => {
    const updated = addFollowUp(
      parentId,
      questionText
    );

    setQuestions(updated);

    localStorage.setItem(
      'questions',
      JSON.stringify(updated)
    );
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">

      <div className="flex justify-between items-center mb-6">

        <h1 className="text-3xl font-bold">
          User Form
        </h1>

        <Link
          to="/"
          className="bg-blue-500 text-white px-4 py-2 rounded"
        >
          Back To Builder
        </Link>

      </div>

      {questions.map((question, index) => (
        <FormQuestion
          key={question.id}
          question={question}
          numbering={`Q${index + 1}`}
          handleAnswer={handleAnswer}
          handleAddFollowUp={handleAddFollowUp}
        />
      ))}
    </div>
  );
};

export default FormPage;
